(()=>{
const key='nympheas-slide-v2-'+location.pathname;let data={};try{data=JSON.parse(localStorage.getItem(key)||'{}')}catch{}let active=null,drag=null,editing=false;
const items=[...document.querySelectorAll('main h1,main h2,main p,main small,main .monogram,main .contents a,main .back,main img,main .video-block')].filter(el=>!el.closest('.video-block')||el.matches('.video-block'));
const ids=items.map((el,i)=>el.dataset.layoutId||el.tagName.toLowerCase()+'-'+i);
const bar=document.createElement('div');bar.style='position:fixed;bottom:14px;right:14px;max-width:calc(100vw - 28px);z-index:999;background:#faf3e5;padding:12px;border:1px solid #a58aa8;color:#705575;font:14px Georgia';bar.innerHTML='<button id="layout-toggle">調整排版</button><span id="layout-controls" hidden> 選取後拖動 · 大小 <input aria-label="元素大小" type="range" min="30" max="220" value="100"><button id="layout-reset">重設</button></span>';document.body.append(bar);const slider=bar.querySelector('input');
function save(){try{localStorage.setItem(key,JSON.stringify(data))}catch{}}
function apply(el,i){const d=data[ids[i]]||{x:0,y:0,s:100};el.style.translate=d.x+'px '+d.y+'px';el.style.scale=d.s/100;if(d.w)el.style.width=d.w+'px'}
items.forEach((el,i)=>{apply(el,i);el.addEventListener('pointerdown',e=>{if(!editing)return;e.preventDefault();e.stopPropagation();if(active)active.style.outline='';active=el;el.style.outline='1px dashed #705575';const d=data[ids[i]]||{x:0,y:0,s:100};data[ids[i]]=d;slider.value=d.s;drag={i,el,x:e.clientX,y:e.clientY,ox:d.x,oy:d.y};el.setPointerCapture(e.pointerId)});el.addEventListener('click',e=>{if(editing)e.preventDefault()})});
window.addEventListener('pointermove',e=>{if(!drag)return;const d=data[ids[drag.i]];d.x=drag.ox+e.clientX-drag.x;d.y=drag.oy+e.clientY-drag.y;apply(drag.el,drag.i)});function end(){if(drag)save();drag=null}window.addEventListener('pointerup',end);window.addEventListener('pointercancel',end);
slider.oninput=()=>{if(!active)return;const i=items.indexOf(active);data[ids[i]].s=+slider.value;apply(active,i);save()};bar.querySelector('#layout-toggle').onclick=()=>{editing=!editing;document.body.classList.toggle('layout-editing',editing);bar.querySelector('#layout-controls').hidden=!editing;items.forEach(el=>{el.style.touchAction=editing?'none':'';el.style.cursor=editing?'move':''});if(!editing&&active)active.style.outline=''};bar.querySelector('#layout-reset').onclick=()=>{data={};items.forEach(apply);save()};
items.forEach((el,i)=>{if(!el.matches('p,h1,h2'))return;el.style.position=el.style.position||'relative';for(const side of ['left','right']){const h=document.createElement('span');h.setAttribute('aria-label',side+' resize');h.style=`position:absolute;${side}:-7px;top:0;width:12px;height:100%;cursor:ew-resize;display:none;touch-action:none;border-${side}:2px solid #a58aa8`;el.append(h);const toggle=bar.querySelector('#layout-toggle');toggle.addEventListener('click',()=>h.style.display=editing?'block':'none');h.onpointerdown=e=>{e.preventDefault();e.stopPropagation();const start=e.clientX,w=el.getBoundingClientRect().width;h.setPointerCapture(e.pointerId);h.onpointermove=ev=>{const width=Math.max(60,w+(ev.clientX-start)*(side==='left'?-1:1));data[ids[i]]=data[ids[i]]||{x:0,y:0,s:100};data[ids[i]].w=width;apply(el,i)};h.onpointerup=()=>{h.onpointermove=null;save()}}}});
})();
